/**
 * @param {Object|Array} obj
 * @return {Object|Array}
 */
var compactObject = function(obj) {
    // Primitives (and null): the caller decides whether to keep them
    if (obj === null || typeof obj !== "object") return obj;

    if (Array.isArray(obj)) {
        const result = [];
        for (const item of obj) {
            const compacted = compactObject(item);
            // Boolean(value) is the official definition of falsy;
            // empty arrays/objects are truthy, so they are kept
            if (Boolean(compacted)) result.push(compacted);
        }
        return result;
    }

    const result = {};
    for (const key of Object.keys(obj)) {
        const compacted = compactObject(obj[key]);
        if (Boolean(compacted)) result[key] = compacted;
    }
    return result;
};
